import csv, numpy as np
def load_idx(sym):
    rows=list(csv.reader(open(f'../persistent/index_data/{sym}.csv')))
    hdr=rows[0]; di={k:i for i,k in enumerate(hdr)}
    dates=[r[di['date']] for r in rows[1:]]
    close=[]
    for r in rows[1:]:
        try: close.append(float(r[di['close']]))
        except: close.append(np.nan)
    return dates, np.array(close)
for s in ['VIX','DXY','USDCNY','USDJPY','EURUSD']:
    dates,c=load_idx(s)
    i=dates.index('2026-07-29') if '2026-07-29' in dates else len(dates)-1
    def r(k):
        return c[i]/c[i-k]-1 if i-k>=0 and c[i-k] else np.nan
    print(f'{s:7s} val={c[i]:9.2f}  1m={r(21)*100:6.1f}%  3m={r(63)*100:6.1f}%  date={dates[i]}')
"

